import{_ as t,o as s,c as e,a5 as d}from"./chunks/framework.CslsFoWx.js";const b=JSON.parse('{"title":"Sessions de caisse","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/04-cash-sessions.md","filePath":"generated/modules/04-cash-sessions.md","lastUpdated":null}'),n={name:"modules/04-cash-sessions.md"};function r(o,a,p,i,l,c){return s(),e("div",null,[...a[0]||(a[0]=[d('<h1 id="sessions-de-caisse" tabindex="-1">Sessions de caisse <a class="header-anchor" href="#sessions-de-caisse" aria-label="Permalink to &quot;Sessions de caisse&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 1 · <a href="/VendoraSystem-docs/specs/04-cash-sessions">spécification complète</a></span></p><p>Vie d&#39;une caisse physique : ouverture avec fond, mouvements d&#39;espèces motivés, rapport X sans effet, clôture avec comptage et écart, rapport Z numéroté, chaîné et archivé. Le cœur est livré et prouvé sur la vraie stack (Android, iOS, serveur, back-office), y compris l&#39;encaissement à la table et la projection serveur des sessions ; restent le comptage par coupure, la supervision des écarts par caissier, la clôture forcée depuis le back-office et les règlements d&#39;ardoise (phase 3).</p><div class="kpis"><div><b>21</b><span>faites</span></div><div><b>8</b><span>partielles</span></div><div><b>2</b><span>à faire</span></div><div><b>0</b><span>bloquées</span></div></div><h2 id="ouverture-vie-de-la-session" tabindex="-1">Ouverture &amp; vie de la session <a class="header-anchor" href="#ouverture-vie-de-la-session" aria-label="Permalink to &quot;Ouverture &amp; vie de la session&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Ouverture avec fond de caisse</strong><br><span class="muted">Le caissier connecté ouvre la session de sa caisse en saisissant le fond de caisse, même sans internet.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CASH-01, RG-CASH-03, RG-CASH-19</td><td>1.x, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-encaissement-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-encaissement-ios">📷</a></td></tr><tr><td><strong>Pas de vente sans session ouverte</strong><br><span class="muted">Toute vente est rattachée à la session ouverte de la caisse ; sans session, l&#39;écran de vente propose l&#39;ouverture.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CASH-04</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-encaissement-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-encaissement-ios">📷</a></td></tr><tr><td><strong>Une seule session ouverte par caisse</strong><br><span class="muted">Une seconde ouverture sur la même caisse est refusée, y compris hors ligne.<br><i>Contrôle local en place ; la détection serveur d&#39;une double ouverture à la sync (sessions marquées en conflit, alerte au gérant, spec §9) n&#39;est pas faite.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CASH-02</td><td>1.x</td><td></td></tr><tr><td><strong>Session restaurée après un crash</strong><br><span class="muted">Après un crash ou une coupure, la session ouverte, ses ventes et son fond sont retrouvés intacts sans ressaisie.<br><i>Persistance et numérotation sans trou survivant au crash couvertes par les tests shared ; le bandeau « Session restaurée après redémarrage » et le brouillon de comptage après un crash pendant la clôture ne sont pas faits.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CASH-16</td><td>1.x</td><td></td></tr></tbody></table><h2 id="mouvements-d-especes" tabindex="-1">Mouvements d&#39;espèces <a class="header-anchor" href="#mouvements-d-especes" aria-label="Permalink to &quot;Mouvements d&#39;espèces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Entrées et sorties d&#39;espèces motivées</strong><br><span class="muted">Le caissier enregistre une entrée (appoint) ou une sortie (dépôt banque, achat fournisseur) avec un motif obligatoire et un montant positif.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CASH-05, RG-CASH-19</td><td>1.x, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-x-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-x-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a></td></tr><tr><td><strong>Correction par mouvement inverse</strong><br><span class="muted">Un mouvement erroné se corrige une seule fois par un mouvement de sens opposé, motif CORRECTION, jamais par modification.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CASH-06</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-x-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-x-ios">📷</a></td></tr><tr><td><strong>PIN manager pour les sorties</strong><br><span class="muted">Une sortie d&#39;espèces exige le PIN d&#39;un manager vérifié hors ligne, et l&#39;approbateur apparaît dans le rapport X.<br><i>Défaut de la spec appliqué (PIN pour toute sortie) ; le seuil configurable par magasin n&#39;est pas fait.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CASH-05</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-pin-manager-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-pin-manager-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-pin-manager-web">📷</a></td></tr><tr><td><strong>Espèces théoriques calculées</strong><br><span class="muted">Le théorique du tiroir est calculé (fond, encaissements nets du rendu, remboursements, mouvements, pourboires espèces, ventes de salle), jamais saisi.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CASH-07</td><td>1.x, 2.9, 2.15, 2.20, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-x-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-encaissement-table">📷</a></td></tr></tbody></table><h2 id="rapport-x" tabindex="-1">Rapport X <a class="header-anchor" href="#rapport-x" aria-label="Permalink to &quot;Rapport X&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Rapport X sans effet</strong><br><span class="muted">Le caissier consulte et imprime un rapport X numéroté (« ne vaut pas clôture ») autant de fois que voulu, chaque édition étant tracée.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CASH-08</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-x-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-x-ios">📷</a></td></tr><tr><td><strong>Rapport X au back-office</strong><br><span class="muted">Le gérant consulte le rapport X d&#39;une session depuis le back-office, avec le même agrégat que la caisse.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CASH-08</td><td>2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a></td></tr></tbody></table><h2 id="cloture-rapport-z" tabindex="-1">Clôture &amp; rapport Z <a class="header-anchor" href="#cloture-rapport-z" aria-label="Permalink to &quot;Clôture &amp; rapport Z&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Clôture avec comptage et écart</strong><br><span class="muted">À la clôture, le montant compté est obligatoire, l&#39;écart est calculé en direct et un commentaire est exigé s&#39;il n&#39;est pas nul.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CASH-09, RG-CASH-10, RG-CASH-11</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-z-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-z-ios">📷</a></td></tr><tr><td><strong>Comptage par coupure</strong><br><span class="muted">Le caissier détaille le fond et le comptage par coupure, le total se calculant automatiquement.<br><i>Optionnel dans la spec (phase 1) ; non planifié au TRACKING — seul le total compté est saisi.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-CASH-03, RG-CASH-09</td><td></td><td></td></tr><tr><td><strong>Rapport Z numéroté et chaîné</strong><br><span class="muted">Chaque clôture produit un Z numéroté sans trou par caisse, haché en SHA-256 et chaîné au précédent, revérifié par le serveur au push.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CASH-12, RG-CASH-13</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-z-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-z-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-z-web">📷</a></td></tr><tr><td><strong>Contenu figé du Z</strong><br><span class="muted">Le Z fige le CA par mode, la TVA par taux, les remises, vendeurs, mouvements, pourboires, ventes de salle et le théorique / compté / écart.<br><i>Contenu complet, dont les règlements d&#39;ardoise (lot 3.4).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CASH-14</td><td>1.x, 2.9, 2.15, 2.20</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-z-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-z-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-z-web">📷</a></td></tr><tr><td><strong>Annulations et retours dans X et Z</strong><br><span class="muted">Les ventes annulées sont exclues, les retours diminuent le CA, et le X comme le Z affichent annulations et retours.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CASH-14</td><td>2.20, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-annulations-retours">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a></td></tr><tr><td><strong>Impression du Z et DUPLICATA</strong><br><span class="muted">Le Z s&#39;imprime automatiquement à la clôture ; toute réimpression, sous PIN manager, est marquée DUPLICATA et tracée.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CASH-15</td><td>1.x, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-z-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-pin-manager-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-pin-manager-ios">📷</a></td></tr><tr><td><strong>Archive des Z au back-office</strong><br><span class="muted">Le gérant consulte l&#39;archive des Z, leur statut d&#39;intégrité et leur détail figé, l&#39;empreinte étant recalculée par le navigateur.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CASH-13, RG-CASH-15</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-z-web">📷</a></td></tr><tr><td><strong>Export PDF du Z</strong><br><span class="muted">Le gérant télécharge le PDF d&#39;un Z généré à la demande depuis le contenu archivé, avec l&#39;empreinte et le statut d&#39;intégrité.<br><i>Export tracé au journal d&#39;audit (2.23) ; pas de mention « DUPLICATA » sur le PDF, police Helvetica limitée au Latin-1.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CASH-15</td><td>2.19, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-export-pdf-z">📷</a></td></tr><tr><td><strong>Clôture forcée par un manager</strong><br><span class="muted">Un manager clôture la session d&#39;un autre utilisateur sur l&#39;appareil, hors ligne, et la clôture est tracée comme forcée.<br><i>La variante back-office en ligne (appareil perdu ou hors service, Z généré côté serveur) n&#39;est pas faite.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td>RG-CASH-18</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-login-pin-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-login-pin-ios">📷</a></td></tr></tbody></table><h2 id="tiroir" tabindex="-1">Tiroir <a class="header-anchor" href="#tiroir" aria-label="Permalink to &quot;Tiroir&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Ouverture du tiroir hors vente</strong><br><span class="muted">Ouvrir le tiroir sans vente exige le PIN d&#39;un manager et un motif ; l&#39;impulsion part en direct et l&#39;ouverture est tracée.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CASH-17</td><td>1.x, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-pin-manager-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-pin-manager-ios">📷</a></td></tr></tbody></table><h2 id="supervision-back-office" tabindex="-1">Supervision back-office <a class="header-anchor" href="#supervision-back-office" aria-label="Permalink to &quot;Supervision back-office&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Journal d&#39;audit des sessions</strong><br><span class="muted">Les éditions de X, les réimpressions de Z (avec approbateur), les exports PDF et les ouvertures de tiroir sont journalisés.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-CASH-08, RG-CASH-15, RG-CASH-17</td><td>1.x, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a></td></tr><tr><td><strong>Page « Sessions de caisse »</strong><br><span class="muted">Le gérant voit les sessions ouvertes et clôturées par caisse, projetées par le serveur avec écart et numéro de Z.<br><i>Lot R7 : filtres période (jours locaux) et caissier, colonne Caissier, sessions d&#39;avant la projection rattrapées au démarrage. Rechargement à la demande (pas de temps réel).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CASH-20</td><td>2.23, R7</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r7-clients-rapports">📷</a></td></tr><tr><td><strong>Écarts cumulés par caissier</strong><br><span class="muted">Le propriétaire suit le cumul et la récurrence des écarts de clôture par caissier et par caisse.<br><i>Lot R7 : tableau « Écarts par caissier » sur la période de clôture (sessions, en manque, en excédent, écart cumulé, plus gros manque), attribués à qui a ouvert la session comme l&#39;anti-fraude.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CASH-20</td><td>2.23, R7</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r7-clients-rapports">📷</a></td></tr><tr><td><strong>Alerte session ouverte &gt; 24 h</strong><br><span class="muted">Le gérant est notifié qu&#39;une session est restée ouverte plus de 24 heures.<br><i>Cas limite de la spec (§9), non planifié ; à rattacher à la supervision (phase 3).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td></td><td></td><td></td></tr><tr><td><strong>Alertes d&#39;intégrité au tableau de bord</strong><br><span class="muted">Les anomalies de Z, de scellement, d&#39;approbation et de projection remontent dans une carte d&#39;alertes du tableau de bord.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CASH-13</td><td>2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a></td></tr></tbody></table><h2 id="encaissement-a-la-table" tabindex="-1">Encaissement à la table <a class="header-anchor" href="#encaissement-a-la-table" aria-label="Permalink to &quot;Encaissement à la table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Politique d&#39;encaissement à la table</strong><br><span class="muted">L&#39;owner choisit au back-office si le téléphone de salle encaisse dans la session de la caisse principale ou dans sa propre session sans tiroir.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CASH-23</td><td>2.15</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-encaissement-table">📷</a></td></tr><tr><td><strong>Session de la caisse principale vue du téléphone</strong><br><span class="muted">Le téléphone de salle suit les sessions des autres caisses et encaisse sur celle de la caisse principale, un bandeau expliquant l&#39;état.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CASH-24</td><td>2.15</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-encaissement-table">📷</a></td></tr><tr><td><strong>Ventes de salle dans le Z de la caisse</strong><br><span class="muted">La caisse principale intègre les ventes encaissées en salle à son historique, son théorique et son Z.<br><i>Badge « salle » absent du ticket imprimé ; pas de filtre « ventes de salle » au back-office.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td>RG-CASH-25</td><td>2.15</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-encaissement-table">📷</a></td></tr><tr><td><strong>Vente de salle reçue après la clôture</strong><br><span class="muted">Une vente de salle arrivée après la clôture n&#39;est jamais perdue : elle est rattachée à la session suivante de la caisse.<br><i>Testé en shared ; aucune capture du cas.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CASH-26</td><td>2.15</td><td></td></tr></tbody></table><h2 id="pourboires-ardoise" tabindex="-1">Pourboires &amp; ardoise <a class="header-anchor" href="#pourboires-ardoise" aria-label="Permalink to &quot;Pourboires &amp; ardoise&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Pourboires dans la session</strong><br><span class="muted">Les pourboires sont comptés hors CA, ventilés par salarié dans le X et le Z, et la part espèces entre dans le théorique.<br><i>Bénéficiaire limité au vendeur connecté ou au pot commun ; pas d&#39;export PDF. Lot R7 : le service se lit « Session n° N · caisse · date ».</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CASH-22</td><td>2.9, 2.14</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-pourboires">📷</a></td></tr><tr><td><strong>Règlements d&#39;ardoise en caisse</strong><br><span class="muted">Le règlement d&#39;une ardoise client est encaissé comme CREDIT_PAYMENT, entre dans le théorique et a sa ligne dans le Z.<br><i>Fait au lot 3.4 : règlements d&#39;ardoise encaissés en caisse, comptés dans le théorique, le X et le Z.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-CASH-21</td><td></td><td></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Comptage par coupure à l&#39;ouverture et à la clôture.</li><li>Détection serveur d&#39;une double ouverture de session à la sync, avec alerte au gérant.</li><li>Bandeau « Session restaurée après redémarrage » et brouillon de comptage après un crash pendant la clôture.</li><li>Seuil de PIN manager par magasin pour les sorties d&#39;espèces.</li><li>Clôture forcée depuis le back-office pour un appareil perdu, avec Z généré côté serveur.</li><li>Écarts cumulés par caissier, filtres et temps réel de la page « Sessions de caisse » (phase 3, spec 12).</li><li>Notification d&#39;une session ouverte depuis plus de 24 h.</li><li>Règlements d&#39;ardoise CREDIT_PAYMENT dans le théorique et le Z (phase 3, spec 06).</li><li>Mention « DUPLICATA » sur le PDF du Z, badge « salle » sur le ticket imprimé, filtre « ventes de salle » au back-office.</li><li>Captures manquantes : impression automatique du Z sur iOS, rapport X complet (CA 5) sur Android, vente de salle reçue après clôture.</li></ul>',22)])])}const g=t(n,[["render",r]]);export{b as __pageData,g as default};
